//import
import '../../../styles/center.css'
import Cat2 from '../../../assests/images/cat2.avif'
//function
const Center =()=>{
    return(
        <div class="container">
            <div class="text-content">
                <h1>Thank you for your interest in making a gift to Animal Care Centers of Rafeeq!</h1>
                <p>Your support is vital to give Rafeeq's shelter animals a second chance towards the better life they deserve. Please join us in our mission to end animal homelessness in Rafeeq by donating today.</p>
            </div>
            <div class="image-content">
                <img src={Cat2} alt="Animal Care"/>
            </div>
        </div>
    )
}
//export
export default Center
